func Cost(books []int) int {
    prices := []int{800, 1520, 2160, 2560, 3000}
    counts := [5]int{}
    for _, book := range books {
        counts[book-1]++
    }
    total := 0
    for counts[0] > 0 {
        sort.Sort(sort.Reverse(sort.IntSlice(counts[:5])))
        // determine group size
        size := 0
        for _, c := range counts {
            if c > 0 { size++ }
